/*
 * Modified by Actuna Sp. z o.o.:
 *   new module (#40): the 503 answer of the drain of the HTTP requests
 *   (httpDrain.js), sent over a response that may already carry headers set by a
 *   handler of a route
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The 503 "unavailable" answer that the drain of the HTTP requests (#40) gives to
 * a request that the flows can no longer answer.
 *
 * The response may already carry headers that a handler of the route set before the
 * flows were stopped (`Set-Cookie`, `Content-Encoding`, `Content-Type`, ...). They
 * would describe a body that is not sent, or leak data of another answer, so
 * they are removed first; only the CORS headers (`Access-Control-*`) and `Vary`
 * stay, which keeps a cross-origin client able to read the 503.
 *
 * The body is fixed, `{code, message}`: no URL, no stack, no text of an error.
 * `httpHold.js` has its own, older, answer and is not changed.
 * @module
 */

const KEEP_HEADERS = /^(access-control-.+|vary)$/i;

/**
 * Sends the 503 answer.
 * @param {import('http').IncomingMessage} req
 * @param {import('http').ServerResponse} res - headers not sent yet
 * @param {Object} opts
 * @param {string} opts.code - the code of the body
 * @param {string} opts.message - the message of the body
 * @param {number|null} [opts.retryAfter] - seconds of `Retry-After`; none for null/undefined
 * @param {boolean} [opts.close] - `Connection: close` (the request was not read to the end)
 * @param {boolean} [opts.clearHeaders] - remove the headers set so far, except `Access-Control-*` and `Vary`
 */
function sendUnavailable(req, res, opts) {
    if (opts.clearHeaders) {
        res.getHeaderNames().forEach(function(name) {
            if (!KEEP_HEADERS.test(name)) {
                res.removeHeader(name);
            }
        });
        // a custom reason phrase of a handler would stay otherwise
        res.statusMessage = undefined;
    }
    const body = JSON.stringify({ code: opts.code, message: opts.message });
    res.statusCode = 503;
    if (opts.retryAfter !== null && opts.retryAfter !== undefined) {
        res.setHeader("Retry-After", String(opts.retryAfter));
    }
    res.setHeader("Cache-Control", "no-store");
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.setHeader("Content-Length", Buffer.byteLength(body));
    if (opts.close) {
        res.setHeader("Connection", "close");
    }
    res.end(req.method === "HEAD" ? undefined : body);
}

module.exports = {
    sendUnavailable
};
